sys_script_fix.script:
var trd = new GlideRecord('sn_customerservice_case');
trd.get('e6d960d047f20210cd4e1ce4316d439b');
var payData = trd.description;

//parse data
var parsedData = JSON.parse(payData);

//Extract Keys of the JSon alone
var jsonKeys = Object.keys(parsedData);

gs.info( "Key Pairs" + jsonKeys);

var jsonValues = [];
for(var i = 0; i<jsonKeys.length; i++){
	jsonValues.push(parsedData[jsonKeys[i]]); //Extract values of each key from the JSON
}

gs.info( "Value Pairs" + jsonValues.toString());
